import sys, math, json
sys.path.insert(0,'/tmp/work/calc')
from data import *

CIRCS = ['C1','C2','C3','C4','C5','C6','C7','C8']
C_MK = 615.0; PH_MK = 7.6
COND_LIMIT = 1.10*C_MK  # 676.5
CLEANER = {'C1':'CL-100','C2':'CL-100','C3':'CL-100','C4':'CL-100','C5':'CL-100','C6':'CL-210','C7':'CL-100','C8':'CL-210'}
C0 = {'CL-100':2600.0,'CL-210':2150.0}
SPENT_PH = {'CL-100':8.4,'CL-210':8.1}
APP_RATE = {'CL-100':1.5,'CL-210':2.0}  # gal per 1000 gal system volume
HAS_CU = {'C1':False,'C2':False,'C3':False,'C4':True,'C5':True,'C6':True,'C7':True,'C8':False}
HAS_ZN = {'C8':True}
PROGRAM = {'C1':'MOLYBDATE-AZOLE','C2':'MOLYBDATE-AZOLE','C3':'MOLYBDATE-AZOLE','C4':'MOLYBDATE-AZOLE',
           'C5':'MOLYBDATE-AZOLE','C6':'POLYSILICATE-AZOLE','C7':'MOLYBDATE-AZOLE','C8':'POLYSILICATE-AZOLE'}
HYDRO_OWED = {'C3':True,'C5':True,'C6':True,'C7':True}
N_F = 1

def circuit_basics(c):
    lines = {k:v for k,v in LINES.items() if v[0]==c}
    pipe = sum(area_ft2(v[1])*v[2]*v[3]*GAL_PER_FT3 for v in lines.values())
    eq = {k:v for k,v in EQUIP.items() if v[0]==c}
    vf = pipe + sum(v[1] for v in eq.values() if not v[8])
    vs = pipe + sum(v[1] for v in eq.values())
    vmin = VCLASS[c]
    qreq = {k: vmin*area_ft2(v[1])*v[3]*448.831 for k,v in lines.items()}
    gov = max(qreq, key=lambda k:(round(qreq[k],6), -int(k)))
    return dict(pipe=pipe, vf=vf, vs=vs, vmin=vmin, qreq=qreq[gov], gov=gov, lines=lines, eq=eq)

def n_rinse(c):
    eta = ETA[c]; c0 = C0[CLEANER[c]]
    nreq = math.log((c0-C_MK)/(COND_LIMIT-C_MK))/eta
    n = math.ceil(nreq - 1e-12)
    cn = C_MK + (c0-C_MK)*math.exp(-eta*n)
    return n, nreq, cn

def hydraulics(c, Q, models, include_bypassed=False):
    b = circuit_basics(c)
    n = len(models); qs = Q/n
    main = 0.0
    for k,v in b['lines'].items():
        if v[3]==1:
            main += headloss(Q, v[1], v[2], v[4], ROUGH[v[5]])[0]
    comp = 0.0
    for k,v in b['eq'].items():
        if (not v[8]) or include_bypassed:
            comp += v[2]*(Q/v[3])**2
    per = []
    for m in models:
        hh = headloss(qs, SKIDS[m]['hose_id'], HOSE_LEN, 0, ROUGH['HOSE'])[0]
        st = STRAINER_DP*(qs/STRAINER_Q)**2
        req = STATIC[c]+main+comp+hh+st
        av = skid_head(m, qs)
        per.append(dict(model=m, qs=qs, hose=hh, strainer=st, req=req, avail=av))
    # governing segment velocity: min velocity leg
    vmin_leg = None
    for k,v in b['lines'].items():
        vel = Q/v[3]/448.831/area_ft2(v[1])
        if vmin_leg is None or vel < vmin_leg[1] - 1e-12:
            vmin_leg = (k, vel, v[1])
    k, vel, idin = vmin_leg
    Re = vel*(idin/12)/NU
    return dict(static=STATIC[c], main=main, comp=comp, per=per, gov=k, vel=vel, id_in=idin, Re=Re)

if __name__ == '__main__':
    tot = {}
    for c in CIRCS:
        b = circuit_basics(c); n, nreq, cn = n_rinse(c)
        print(c, f"Vf={b['vf']:.1f} Vs={b['vs']:.1f} Qreq={b['qreq']:.2f} gov={b['gov']} n_r={n} nreq={nreq:.4f} Cn={cn:.2f} "
              f"m_cond={(COND_LIMIT-cn)/COND_LIMIT:.5f} m_disp={(n-nreq)/nreq:.5f}")
