import sys; sys.path.insert(0,'/tmp/work/calc')
from eng import *
CHAIN = ['C1','C5','C3','C4','C8','C2','C6','C7']
def cascade_map(chain):
    donor_of = {}; recv_of = {}
    for a,b in zip(chain, chain[1:]):
        donor_of[b] = a; recv_of[a] = b
    return donor_of, recv_of
def accounting(chain=CHAIN, turnover='RETAIN_AND_TOP_UP'):
    donor_of, recv_of = cascade_map(chain)
    rows = {}
    for c in CIRCS:
        b = circuit_basics(c); vf, vs = b['vf'], b['vs']
        n, _, _ = n_rinse(c)
        cc = 1 if c in donor_of else 0
        d = circuit_basics(recv_of[c])['vf'] if c in recv_of else 0.0
        r = {}
        if HYDRO_OWED.get(c): r['HYDRO'] = (vf, vf, 'SEWER')
        r['INITIAL_FLUSH'] = (N_F*vf, N_F*vf, 'SEWER')
        haul = HAS_CU[c] or HAS_ZN.get(c, False)
        r['CHEM_CLEAN'] = (vf, vf, 'HAUL' if haul else 'SEWER')
        r['DRAIN_RINSE'] = ((n-cc)*vf, (n-1)*vf - d, 'SEWER')
        r['PASSIVATE'] = (0.0, 0.0, 'NONE')
        r['HOLD'] = (0.0, 0.0, 'NONE')
        if turnover == 'RETAIN_AND_TOP_UP':
            r['FINAL_FILL'] = (vs-vf, 0.0, 'NONE')
        else:
            r['FINAL_FILL'] = (vs, vf, 'HAUL')
        rows[c] = r
    return rows
if __name__ == '__main__':
    rows = accounting()
    sew = haul = draw = 0
    for c in CIRCS:
        for s,(w,e,rt) in rows[c].items():
            draw += w
            if rt=='SEWER': sew += e
            elif rt=='HAUL': haul += e
        print(c, {s:(round(w),round(e),rt) for s,(w,e,rt) in rows[c].items()})
    vs_tot = sum(circuit_basics(c)['vs'] for c in CIRCS)
    print(f"draw={draw:.1f} sewer={sew:.1f} haul={haul:.1f} Vs_total={vs_tot:.1f} balance={draw-sew-haul-vs_tot:.3f}")
    print(f"cap margin = {(500000-sew)/500000:.5f}")
