import sys, math, json, time
sys.path.insert(0,'/tmp/work/calc')
import numpy as np
from scipy.optimize import milp, LinearConstraint, Bounds
from scipy.sparse import lil_matrix, csr_matrix
from plan_params import *

SL = float(sys.argv[1]) if len(sys.argv)>1 else 0.5     # slot length h
HDAYS = int(sys.argv[2]) if len(sys.argv)>2 else 14
TLIM = float(sys.argv[3]) if len(sys.argv)>3 else 300
NS = int(HDAYS*24/SL)
acc = accounting()
donor_of, recv_of = cascade_map(CHAIN)

def day_cap(d):
    if d in (2,3): return 61000.0, 31000.0
    if d == 6: return 30000.0, 0.0
    return 92000.0, 62000.0

# ---- blocks
blocks = []  # dict(name, circ, kind, dur_exact, res, crew, water_profile: list of (t0rel, t1rel, gal))
for c in CIRCS:
    D = durations(c); b = circuit_basics(c); vf = b['vf']
    res = 'FS1200' if SKIDMODEL[c]==['FS-1200'] else 'FS600'
    if HYDRO_OWED.get(c):
        blocks.append(dict(name=f'H_{c}', circ=c, kind='H', dur=HYDRO_H, res=None, wp=[(0,HYDRO_H,vf)]))
    fc = D['flush']+D['clean']
    blocks.append(dict(name=f'FC_{c}', circ=c, kind='FC', dur=fc, res=res,
                       wp=[(0,D['flush'],N_F*vf),(D['flush'],fc,vf)]))
    rinse_draw = acc[c]['DRAIN_RINSE'][0]
    if c == 'C1':
        for i in range(6):
            blocks.append(dict(name=f'D{i+1}_C1', circ=c, kind='D', dur=D['td'], res=res, wp=[(0,D['td'],rinse_draw/6)]))
        blocks.append(dict(name='PASS_C1', circ=c, kind='P', dur=D['passivate'], res=res, wp=[]))
    else:
        rp = D['rinse']+D['passivate']
        blocks.append(dict(name=f'RP_{c}', circ=c, kind='RP', dur=rp, res=res, wp=[(0,D['rinse'],rinse_draw)], rinse=D['rinse']))
B = {bl['name']:i for i,bl in enumerate(blocks)}
for bl in blocks:
    bl['ns'] = int(math.ceil(bl['dur']/SL - 1e-9))

# precedence arcs: (a, b, lag_h) meaning start_b >= start_a + lag_h
arcs = []
for c in CIRCS:
    if HYDRO_OWED.get(c): arcs.append((f'H_{c}', f'FC_{c}', HYDRO_H))
    fc = blocks[B[f'FC_{c}']]['dur']
    if c=='C1':
        arcs.append(('FC_C1','D1_C1',fc))
        for i in range(1,6): arcs.append((f'D{i}_C1', f'D{i+1}_C1', blocks[B['D1_C1']]['dur']))
        arcs.append(('D6_C1','PASS_C1',blocks[B['D1_C1']]['dur']))
    else:
        arcs.append((f'FC_{c}', f'RP_{c}', fc))
# chain: receiver RP start >= donor rinse end
for recv, don in donor_of.items():
    if don=='C1':
        arcs.append(('D6_C1', f'RP_{recv}', blocks[B['D1_C1']]['dur']))
    else:
        arcs.append((f'RP_{don}', f'RP_{recv}', blocks[B[f'RP_{don}']]['rinse']))

# earliest starts (in slots) via forward pass
ES = {bl['name']:0 for bl in blocks}
for bl in blocks:
    if bl['res']=='FS1200': ES[bl['name']] = int(math.ceil(48/SL))
changed=True
while changed:
    changed=False
    for a,b,lag in arcs:
        v = ES[a] + int(math.ceil(lag/SL - 1e-9))
        if v > ES[b]: ES[b]=v; changed=True
LS = {bl['name']: NS - bl['ns'] for bl in blocks}
for bl in blocks:
    if bl['kind']=='H': LS[bl['name']] = min(LS[bl['name']], int((144-HYDRO_H)/SL))
changed=True
while changed:
    changed=False
    for a,b,lag in arcs:
        v = LS[b] - int(math.ceil(lag/SL - 1e-9))
        if v < LS[a]: LS[a]=v; changed=True
for bl in blocks:
    assert ES[bl['name']] <= LS[bl['name']], bl['name']

# variables
var = []  # (block idx, start slot)
for i,bl in enumerate(blocks):
    for s in range(ES[bl['name']], LS[bl['name']]+1):
        var.append((i,s))
nx = len(var)
ndays = HDAYS; nsh = HDAYS*2
# extra vars: U12[d], U6[d], K[s], truck[d], draw[d]
iU12 = nx; iU6 = iU12+ndays; iK = iU6+ndays; iTR = iK+nsh; iDR = iTR+ndays; nv = iDR+ndays
c_obj = np.zeros(nv)
c_obj[iU12:iU12+ndays] = 790
c_obj[iU6:iU6+ndays] = 430
c_obj[iK:iK+nsh] = 820
c_obj[iTR:iTR+ndays] = 13.6/1000
# tiny tie-breaker: prefer earlier finishes
for j,(i,s) in enumerate(var): c_obj[j] = 1e-4*s*SL
rows=[]; lo=[]; hi=[]
def addrow(coefs, l, h):
    rows.append(coefs); lo.append(l); hi.append(h)
byblock = {}
for j,(i,s) in enumerate(var): byblock.setdefault(i,[]).append((j,s))
for i in byblock: addrow({j:1 for j,s in byblock[i]}, 1, 1)
# cover lists per slot per resource
cov = {'FS1200':[dict() for _ in range(NS)], 'FS600':[dict() for _ in range(NS)], 'CREW':[dict() for _ in range(NS)]}
for j,(i,s) in enumerate(var):
    bl = blocks[i]
    for t in range(s, s+bl['ns']):
        if bl['res']: cov[bl['res']][t][j]=1
        cov['CREW'][t][j]=1
spd = int(24/SL); sps = int(12/SL)
for t in range(NS):
    d = t//spd; sh = t//sps
    if cov['FS1200'][t]:
        r = dict(cov['FS1200'][t]); r[iU12+d] = -1; addrow(r, -np.inf, 0)
    if cov['FS600'][t]:
        r = dict(cov['FS600'][t]); r[iU6+d] = -1; addrow(r, -np.inf, 0)
    if cov['CREW'][t]:
        r = dict(cov['CREW'][t]); r[iK+sh] = -1; addrow(r, -np.inf, 0)
# water per day
def overlap(a0,a1,b0,b1): return max(0.0, min(a1,b1)-max(a0,b0))
wrow = [dict() for _ in range(ndays)]
for j,(i,s) in enumerate(var):
    bl = blocks[i]; t0 = s*SL
    for (r0,r1,gal) in bl['wp']:
        if gal<=0: continue
        for d in range(ndays):
            ov = overlap(t0+r0,t0+r1,24*d,24*d+24)
            if ov>0: wrow[d][j] = wrow[d].get(j,0)+gal*ov/(r1-r0)
for d in range(ndays):
    r = dict(wrow[d]); r[iDR+d] = -1; addrow(r, 0, 0)
    cap, met = day_cap(d)
    addrow({iTR+d:1, iDR+d:-1}, -met, np.inf)
# precedence
for a,b,lag in arcs:
    r = {}
    for j,s in byblock[B[b]]: r[j] = r.get(j,0)+s*SL
    for j,s in byblock[B[a]]: r[j] = r.get(j,0)-s*SL
    addrow(r, lag-1e-6, np.inf)
# milestones: clean end <= 528 ; passivate end <= 720
for bl in blocks:
    if bl['kind']=='FC':
        addrow({j:s*SL for j,s in byblock[B[bl['name']]]}, -np.inf, 528-bl['dur'])
    if bl['kind'] in ('RP','P'):
        addrow({j:s*SL for j,s in byblock[B[bl['name']]]}, -np.inf, 720-bl['dur'])
A = lil_matrix((len(rows), nv))
for k,r in enumerate(rows):
    for j,v in r.items(): A[k,j]=v
A = csr_matrix(A)
lb = np.zeros(nv); ub = np.ones(nv)
ub[iU12:iU12+ndays]=1; ub[iU6:iU6+ndays]=2; ub[iK:iK+nsh]=2
for d in range(ndays):
