import sys, math, json, csv, os, io, zipfile
sys.path.insert(0, '/tmp/work/calc')
from plan_params import *
from chem import chem_rows, PROD, INHIB, choose_levels, ppm_to_gal, pk

UNIT_MODEL = {'FS-600-A': 'FS-600', 'FS-600-B': 'FS-600', 'FS-1200-A': 'FS-1200'}
UNIT_AVAIL_FROM = {'FS-600-A': 0.0, 'FS-600-B': 0.0, 'FS-1200-A': 48.0}
RATE = {'FS-600': 430.0, 'FS-1200': 790.0}
CREW_RATE = 820.0
MET_RATE = 6.20; TRUCK_RATE = 19.80; SEWER_RATE = 9.40; HAUL_RATE = 168.0
CAP = 500000.0
SOFTENER_GRAINS = 88000.0
HARD_GPG = 288.0 / 17.118
SOFT_GAL_PER_DAY = SOFTENER_GRAINS / HARD_GPG
TM = {'TM-1': 6 * 24, 'TM-2': 22 * 24, 'TM-3': 44 * 24, 'TM-4': 47 * 24}
STAGES = ['HYDRO', 'INITIAL_FLUSH', 'CHEM_CLEAN', 'DRAIN_RINSE', 'PASSIVATE', 'HOLD', 'FINAL_FILL']
PUMPED = ['INITIAL_FLUSH', 'CHEM_CLEAN', 'DRAIN_RINSE', 'PASSIVATE', 'FINAL_FILL']
FLUSHING = ['INITIAL_FLUSH', 'CHEM_CLEAN', 'DRAIN_RINSE']


def ceil2(x):
    return math.ceil(x * 100 - 1e-7) / 100.0


def day_caps(d):
    if d in (2, 3):
        return 61000.0, 31000.0
    if d == 6:
        return 30000.0, 0.0
    return 92000.0, 62000.0


def overlap(a0, a1, b0, b1):
    return max(0.0, min(a1, b1) - max(a0, b0))


ACC = accounting()
DONOR_OF, RECV_OF = cascade_map(CHAIN)
BASIC = {c: circuit_basics(c) for c in CIRCS}
NR = {c: n_rinse(c) for c in CIRCS}


def stage_durs(c, ff_flow):
    b = BASIC[c]; vf, vs = b['vf'], b['vs']; Q = FLOW[c]; n = NR[c][0]
    td = vf / Q / 60.0
    return dict(td=td,
                HYDRO=HYDRO_H,
                INITIAL_FLUSH=ceil2(N_F * td),
                CHEM_CLEAN=max(CLEAN_H, ceil2(td)),
                DRAIN_RINSE=ceil2(n * td),
                PASSIVATE=ceil2(td + RECIRC_H),
                FINAL_FILL=ceil2((vs - vf) / ff_flow / 60.0 + RECIRC_H),
                att=dict(HYDRO=HYDRO_H, INITIAL_FLUSH=N_F * td, CHEM_CLEAN=max(CLEAN_H, td), DRAIN_RINSE=n * td,
                         PASSIVATE=td + RECIRC_H, FINAL_FILL=(vs - vf) / ff_flow / 60.0 + RECIRC_H, HOLD=0.0))


def make_activities(spec):
    """spec: dict blocks: {name: (start, units, crew)}, ff: {circ: (start, units, crew, flow)}"""
    acts = []
    ffq = {c: spec['ff'][c][3] for c in CIRCS}
    for c in CIRCS:
        D = stage_durs(c, ffq[c])
        if HYDRO_OWED.get(c):
            s, u, cr = spec['blocks'][f'H_{c}']
            acts.append(dict(circ=c, stage='HYDRO', start=s, finish=s + D['HYDRO'], units=[], crew=cr))
        s, u, cr = spec['blocks'][f'FC_{c}']
        f1 = s + D['INITIAL_FLUSH']
        acts.append(dict(circ=c, stage='INITIAL_FLUSH', start=s, finish=f1, units=u, crew=cr))
        acts.append(dict(circ=c, stage='CHEM_CLEAN', start=f1, finish=f1 + D['CHEM_CLEAN'], units=u, crew=cr))
        if c == 'C1':
            part = ceil2(D['DRAIN_RINSE'] / 3.0)
            for k in range(3):
                s, u, cr = spec['blocks'][f'D{k + 1}_C1']
                acts.append(dict(circ=c, stage='DRAIN_RINSE', start=s, finish=s + part, units=u, crew=cr))
            s, u, cr = spec['blocks']['PASS_C1']
            acts.append(dict(circ=c, stage='PASSIVATE', start=s, finish=s + D['PASSIVATE'], units=u, crew=cr))
        else:
            s, u, cr = spec['blocks'][f'RP_{c}']
            f1 = s + D['DRAIN_RINSE']
            acts.append(dict(circ=c, stage='DRAIN_RINSE', start=s, finish=f1, units=u, crew=cr))
            acts.append(dict(circ=c, stage='PASSIVATE', start=f1, finish=f1 + D['PASSIVATE'], units=u, crew=cr))
        pend = max(a['finish'] for a in acts if a['circ'] == c and a['stage'] == 'PASSIVATE')
        s, u, cr, q = spec['ff'][c]
        acts.append(dict(circ=c, stage='HOLD', start=pend, finish=s, units=[], crew=None))
        acts.append(dict(circ=c, stage='FINAL_FILL', start=s, finish=s + D['FINAL_FILL'], units=u, crew=cr))
    for a in acts:
        a['start'] = round(a['start'], 3); a['finish'] = round(a['finish'], 3)
    # ids
    acts.sort(key=lambda a: (a['start'], a['circ']))
    cnt = {}
    for a in acts:
        k = (a['circ'], a['stage']); cnt[k] = cnt.get(k, 0) + 1
        a['id'] = f"{a['circ']}-{a['stage']}" + (f"-{cnt[k]}" if (a['circ'], a['stage']) == ('C1', 'DRAIN_RINSE') else '')
    # water per activity: stage water spread over activity hours
    for c in CIRCS:
        for st in STAGES:
            al = [a for a in acts if a['circ'] == c and a['stage'] == st]
            if not al:
                continue
            w = ACC[c][st][0] if st in ACC[c] else 0.0
            if st == 'HYDRO' and not HYDRO_OWED.get(c):
                w = 0.0
            tot_h = sum(a['finish'] - a['start'] for a in al)
            for a in al:
                a['water'] = w * (a['finish'] - a['start']) / tot_h if tot_h > 0 else 0.0
    # predecessors
    def last(c, st):
        al = [a for a in acts if a['circ'] == c and a['stage'] == st]
        return max(al, key=lambda a: a['finish']) if al else None
    for a in acts:
        c = a['circ']; preds = []
        order = [s for s in STAGES if any(x['circ'] == c and x['stage'] == s for x in acts)]
        i = order.index(a['stage'])
        if a['stage'] == 'DRAIN_RINSE' and c == 'C1':
            same = sorted([x for x in acts if x['circ'] == c and x['stage'] == 'DRAIN_RINSE'], key=lambda x: x['start'])
            j = same.index(a)
            preds.append(last(c, 'CHEM_CLEAN')['id'] if j == 0 else same[j - 1]['id'])
        elif i > 0:
            preds.append(last(c, order[i - 1])['id'])
        if a['stage'] == 'DRAIN_RINSE' and c in DONOR_OF:
            preds.append(last(DONOR_OF[c], 'DRAIN_RINSE')['id'])
        a['preds'] = preds
    return acts


def evaluate(acts, verbose=False):
    ffq = {}
    for a in acts:
        if a['stage'] == 'FINAL_FILL':
            pass
    probs = []
    ndays = int(math.ceil(max(a['finish'] for a in acts) / 24.0)) + 1
    # ---- unit overlap / availability
    for u in UNIT_MODEL:
        al = sorted([a for a in acts if u in a['units']], key=lambda a: a['start'])
        for x, y in zip(al, al[1:]):
            if y['start'] < x['finish'] - 1e-6:
                probs.append(f'unit {u} overlap {x["id"]} {y["id"]}')
        for a in al:
            if a['start'] < UNIT_AVAIL_FROM[u] - 1e-9:
                probs.append(f'unit {u} not available for {a["id"]}')
    # crew overlap
    for cr in ('CREW-1', 'CREW-2'):
        al = sorted([a for a in acts if a['crew'] == cr], key=lambda a: a['start'])
        for x, y in zip(al, al[1:]):
            if y['start'] < x['finish'] - 1e-6:
                probs.append(f'crew {cr} overlap {x["id"]} {y["id"]}')
    # precedence
    byid = {a['id']: a for a in acts}
    for a in acts:
        for p in a['preds']:
            if byid[p]['finish'] > a['start'] + 1e-6:
                probs.append(f'precedence {p} -> {a["id"]}')
    # hold length
    for c in CIRCS:
        h = [a for a in acts if a['circ'] == c and a['stage'] == 'HOLD'][0]
        if h['finish'] - h['start'] < HOLD_H - 1e-6:
            probs.append(f'hold short {c}')
    # milestones
    for a in acts:
        if a['stage'] == 'HYDRO' and a['finish'] > TM['TM-1'] + 1e-6: probs.append(f'TM-1 {a["id"]}')
        if a['stage'] == 'CHEM_CLEAN' and a['finish'] > TM['TM-2'] + 1e-6: probs.append(f'TM-2 {a["id"]}')
        if a['stage'] == 'HOLD' and a['finish'] > TM['TM-3'] + 1e-6: probs.append(f'TM-3 {a["id"]}')
        if a['finish'] > TM['TM-4'] + 1e-6: probs.append(f'TM-4 {a["id"]}')
    # power: per location simultaneous
    events = sorted(set([a['start'] for a in acts] + [a['finish'] for a in acts]))
    power = {}
    for loc in PANEL_KW:
        mx = 0
        for t0, t1 in zip(events, events[1:]):
            tm = (t0 + t1) / 2
            kw = 0
            for a in acts:
                if a['units'] and LOC[a['circ']] == loc and a['start'] <= tm < a['finish']:
                    kw += sum(SKIDS[UNIT_MODEL[u]]['kw'] for u in a['units'])
            mx = max(mx, kw)
        power[loc] = mx
        if mx > PANEL_KW[loc]:
            probs.append(f'power {loc} {mx}')
    # ---- water per day
    draw = [0.0] * ndays; draw_c = [{c: 0.0 for c in CIRCS} for _ in range(ndays)]
    soft = [0.0] * ndays
    for a in acts:
        dur = a['finish'] - a['start']
        if a.get('water', 0) <= 0 or dur <= 0:
            continue
        for d in range(ndays):
            ov = overlap(a['start'], a['finish'], 24 * d, 24 * d + 24)
            if ov > 0:
                draw[d] += a['water'] * ov / dur; draw_c[d][a['circ']] += a['water'] * ov / dur
                if a['stage'] == 'FINAL_FILL':
                    soft[d] += a['water'] * ov / dur
    met = []; trk = []
    for d in range(ndays):
        cap, mcap = day_caps(d)
        if draw[d] > cap + 1e-6:
            probs.append(f'water day {d} {draw[d]:.0f} > {cap}')
        if soft[d] > SOFT_GAL_PER_DAY + 1e-6:
            probs.append(f'softener day {d} {soft[d]:.0f} > {SOFT_GAL_PER_DAY:.0f}')
        met.append(min(draw[d], mcap)); trk.append(max(0.0, draw[d] - mcap))
    tot_draw = sum(draw)
    water_cost = (sum(met) * MET_RATE + sum(trk) * TRUCK_RATE) / 1000.0
    avg_rate = water_cost / tot_draw * 1000.0
    # ---- unit-days
    unit_days = {u: [] for u in UNIT_MODEL}
    unit_cost_c = {c: 0.0 for c in CIRCS}
    for u in UNIT_MODEL:
        al = [a for a in acts if u in a['units']]
        for d in range(ndays):
            hrs = {}
            for c in CIRCS:
                iv = sorted([(max(a['start'], 24 * d), min(a['finish'], 24 * d + 24)) for a in al if a['circ'] == c
                             and overlap(a['start'], a['finish'], 24 * d, 24 * d + 24) > 0])
                tot = 0.0; cur = None
                for s0, s1 in iv:
                    if cur is None: cur = [s0, s1]
                    elif s0 <= cur[1]: cur[1] = max(cur[1], s1)
                    else: tot += cur[1] - cur[0]; cur = [s0, s1]
                if cur: tot += cur[1] - cur[0]
                if tot > 0: hrs[c] = tot
            if hrs:
                unit_days[u].append(d)
                T = sum(hrs.values())
                if T > 24 + 1e-6: probs.append(f'unit {u} >24h day {d}')
                for c, h in hrs.items():
                    unit_cost_c[c] += RATE[UNIT_MODEL[u]] * h / T
    # ---- crew shifts
    att = {}
    for c in CIRCS:
        ffa = [a for a in acts if a['circ'] == c and a['stage'] == 'FINAL_FILL'][0]
        q = ffa.get('flow', None)
    nsh = ndays * 2
    crew_sh = {cr: [] for cr in ('CREW-1', 'CREW-2')}
    crew_cost_c = {c: 0.0 for c in CIRCS}
    crew_hours = {}
    for cr in crew_sh:
        for s in range(nsh):
            hrs = {}
            for a in acts:
                if a['crew'] != cr: continue
                ov = overlap(a['start'], a['finish'], 12 * s, 12 * s + 12)
                if ov <= 0: continue
                h = a['att_h'] * ov / (a['finish'] - a['start'])
                if h > 0: hrs[a['circ']] = hrs.get(a['circ'], 0) + h
            if hrs:
                crew_sh[cr].append(s)
                T = sum(hrs.values())
                if T > 12 + 1e-6: probs.append(f'crew {cr} >12h shift {s}')
                for c, h in hrs.items():
                    crew_cost_c[c] += CREW_RATE * h / T
    # ---- effluent & chemicals
    eff_c = {}; sew_tot = 0; haul_tot = 0
    for c in CIRCS:
        sw = sum(e for st, (w, e, rt) in ACC[c].items() if rt == 'SEWER')
        hl = sum(e for st, (w, e, rt) in ACC[c].items() if rt == 'HAUL')
        sew_tot += sw; haul_tot += hl
        eff_c[c] = (sw * SEWER_RATE + hl * HAUL_RATE) / 1000.0
    if sew_tot > CAP: probs.append('sewer cap exceeded')
    chem_c = {}
    for c in CIRCS:
        chem_c[c] = sum(PROD[r['product_id']]['price'] * r['packages'] for r in chem_rows(c))
    water_c = {c: sum(ACC[c][st][0] for st in ACC[c]) * avg_rate / 1000.0 for c in CIRCS}
    per_c = {c: dict(skid_rental=unit_cost_c[c], crew=crew_cost_c[c], water=water_c[c], effluent=eff_c[c],
                     chemicals=chem_c[c]) for c in CIRCS}
    for c in CIRCS: per_c[c]['total'] = sum(per_c[c].values())
    total = sum(p['total'] for p in per_c.values())
    res = dict(probs=probs, draw=draw, draw_c=draw_c, met=met, trk=trk, soft=soft, water_cost=water_cost, avg_rate=avg_rate,
               unit_days=unit_days, crew_sh=crew_sh, per_c=per_c, total=total, sew_tot=sew_tot, haul_tot=haul_tot,
               power=power, ndays=ndays,
               breakdown=dict(skid_rental=sum(RATE[UNIT_MODEL[u]] * len(d) for u, d in unit_days.items()),
                              crew=CREW_RATE * sum(len(s) for s in crew_sh.values()),
                              water=water_cost, effluent=sum(eff_c.values()), chemicals=sum(chem_c.values())))
    if verbose:
        print('PROBLEMS:', probs)
        print('unit days', {u: d for u, d in unit_days.items()})
        print('crew shifts', {k: v for k, v in crew_sh.items()}, sum(len(v) for v in crew_sh.values()))
        print('draw', [round(x) for x in draw]); print('truck', [round(x) for x in trk], round(sum(trk)))
        print('soft', [round(x) for x in soft])
        print('breakdown', {k: round(v, 2) for k, v in res['breakdown'].items()}, 'total', round(total, 2))
    return res


def attach_att(acts, spec):
    ffq = {c: spec['ff'][c][3] for c in CIRCS}
    for c in CIRCS:
        D = stage_durs(c, ffq[c])
        for st in STAGES:
            al = [a for a in acts if a['circ'] == c and a['stage'] == st]
            if not al: continue
            tot_h = sum(a['finish'] - a['start'] for a in al)
            A = D['att'][st] if st != 'HOLD' else 0.0
            for a in al:
                a['att_h'] = A * (a['finish'] - a['start']) / tot_h if tot_h > 0 else 0.0
                a['flow'] = ffq[c] if st == 'FINAL_FILL' else (FLOW[c] if st in PUMPED else None)
    return acts

