import sys, json, itertools
sys.path.insert(0,'/tmp/work/calc')
from spec_s1 import *
def assign_crews(blocks_times):
    """blocks_times: list of (name, start, end). Assign CREW-1/CREW-2 minimizing crew-shifts via DFS."""
    items = sorted(blocks_times, key=lambda x: x[1])
    best = [None, 10**9]
    def shifts_of(assign):
        sh = {('CREW-1'):set(), ('CREW-2'):set()}
        for (n,s,e),cr in zip(items, assign):
            k0 = int(s//12); k1 = int((e-1e-9)//12)
            for k in range(k0, k1+1): sh[cr].add(k)
        return sum(len(v) for v in sh.values())
    # greedy with lookahead: try both crews, prune by overlap
    import functools
    n = len(items)
    assign = [None]*n
    def ok(i, cr):
        for j in range(i):
            if assign[j]==cr and items[j][2] > items[i][1]+1e-9 and items[i][2] > items[j][1]+1e-9: return False
        return True
    def partial_cost(i):
        return shifts_of(assign[:i]) if i>0 else 0
    sys.setrecursionlimit(10000)
    def dfs(i):
        if i==n:
            c = shifts_of(assign)
            if c < best[1]: best[0]=list(assign); best[1]=c
            return
        if partial_cost(i) >= best[1]: return
        for cr in ('CREW-1','CREW-2'):
            if i==0 and cr=='CREW-2': continue
            if ok(i,cr):
                assign[i]=cr; dfs(i+1); assign[i]=None
    dfs(0)
    return {items[i][0]: best[0][i] for i in range(n)}, best[1]
def spec_from_solution(sol, unit_map, ff_plan):
    blocks = {}
    times = []
    for name, st in sol.items():
        times.append((name, st, st+block_dur(name)))
    crews, nsh = assign_crews(times)
    for name, st in sol.items():
        blocks[name] = (st, unit_map[name], crews[name])
    return dict(blocks=blocks, ff=ff_plan), nsh
def ff_days(plan_days, start_hours):
    ff = {}
    for day, circs in plan_days:
        t = start_hours.get(day, 24*day)
        for c in circs:
            ff[c] = (round(t,3),[A],'CREW-1',FFQ[c]); t += ff_dur(c)
