import zipfile, csv, io, json, math, re, sys
ZP = '/filesystem/final_batch4__mechanical_task5_pcw_flush_mop__blind/output/submission.zip'
z = zipfile.ZipFile(ZP)
need = ['flush_plan.csv', 'chemistry_plan.csv', 'acceptance_matrix.csv', 'schedule.csv', 'resources.json', 'constraint_register.csv', 'MOP.md']
names = z.namelist()
for n in need:
    assert n in names, n
def rd(n):
    return list(csv.DictReader(io.StringIO(z.read(n).decode())))
fp = rd('flush_plan.csv'); ch = rd('chemistry_plan.csv'); am = rd('acceptance_matrix.csv'); sc = rd('schedule.csv'); rg = rd('constraint_register.csv')
res = json.loads(z.read('resources.json')); mop = z.read('MOP.md').decode()
STAGES = {'HYDRO', 'INITIAL_FLUSH', 'CHEM_CLEAN', 'DRAIN_RINSE', 'PASSIVATE', 'HOLD', 'FINAL_FILL'}
UNITS = {'FS-600-A', 'FS-600-B', 'FS-1200-A'}
BAD = {'TBD', 'TBA', 'TO BE DETERMINED', 'TO BE ADVISED', 'NAN', 'INF', 'XXX', '<FILL IN>'}
NUMCOLS = ['flow_gpm', 'velocity_fps', 'reynolds', 'required_head_ft', 'skid_head_avail_ft', 'duration_h', 'circuit_volume_gal',
           'system_volume_gal', 'passes', 'water_volume_gal', 'discharge_volume_gal', 'discharge_ph', 'discharge_temp_f', 'target_ppm',
           'product_quantity', 'basis_volume_gal', 'ph_target_lo', 'ph_target_hi', 'threshold_value', 'start_h', 'finish_h']
errs = []
for fn, rows in [('flush_plan', fp), ('chemistry_plan', ch), ('acceptance_matrix', am), ('schedule', sc)]:
    for r in rows:
        for k, v in r.items():
            if k in NUMCOLS and v is not None and v.strip().upper() in BAD:
                errs.append(f'FATAL token {fn}.{k}={v}')
            if k in NUMCOLS and v not in (None, '') and v.strip().upper() not in ('N/A', 'NONE', '--'):
                try: float(v)
                except: errs.append(f'non-numeric {fn}.{k}={v}')
for r in fp + sc:
    if r['stage'] not in STAGES: errs.append(f'bad stage {r["stage"]}')
    if r['stage'] not in ('HYDRO', 'HOLD'):
        toks = [t.strip() for t in r['skid_id'].split('+')]
        if not all(t in UNITS for t in toks): errs.append(f'bad skid {r["circuit_id"]} {r["stage"]} {r["skid_id"]}')
# independent hydraulic recheck
NU = 1.08e-5; G = 32.17
lines = {'1043': (6.065, 4), '2011': (7.981, 1), '2023': (6.065, 2), '4021': (6.065, 1), '4033': (4.026, 3), '4041': (6.065, 1), '5011': (6.065, 1), '6013': (3.068, 2)}
vmin = {'C1': 3.28, 'C2': 4, 'C3': 4, 'C4': 4, 'C5': 4, 'C6': 4, 'C7': 3.28, 'C8': 3.28}
for r in fp:
    if r['stage'] in ('INITIAL_FLUSH', 'CHEM_CLEAN', 'DRAIN_RINSE'):
        d, legs = lines[r['governing_segment']]
        v = float(r['flow_gpm']) / legs / 448.831 / (math.pi / 4 * (d / 12) ** 2)
        if v < vmin[r['circuit_id']] - 1e-9: errs.append(f'velocity {r["circuit_id"]} {r["stage"]} {v:.3f}')
        if abs(v - float(r['velocity_fps'])) > 0.002: errs.append(f'velocity mismatch {r["circuit_id"]}')
    if r['stage'] not in ('HYDRO', 'HOLD'):
        if float(r['required_head_ft']) > float(r['skid_head_avail_ft']): errs.append(f'head {r["circuit_id"]} {r["stage"]}')
# durations: rinse >= n*Vf/Q, clean >= 24
for r in fp:
    vf = float(r['circuit_volume_gal']); dur = float(r['duration_h'])
    if r['stage'] == 'CHEM_CLEAN' and dur < 24 - 1e-9: errs.append('clean dur')
    if r['stage'] == 'DRAIN_RINSE':
        req = int(r['passes']) * vf / float(r['flow_gpm']) / 60
        if dur < req - 1e-6: errs.append(f'rinse dur {r["circuit_id"]}')
    if r['stage'] == 'HOLD' and dur < 336: errs.append('hold')
    if r['stage'] == 'HYDRO' and (dur < 2 or float(r['test_pressure_psig']) < 125): errs.append('hydro')
# schedule sums vs flush plan durations
from collections import defaultdict
occ = defaultdict(float)
for r in sc: occ[(r['circuit_id'], r['stage'])] += float(r['finish_h']) - float(r['start_h'])
for r in fp:
    if abs(occ[(r['circuit_id'], r['stage'])] - float(r['duration_h'])) > 0.011: errs.append(f'dur mismatch {r["circuit_id"]} {r["stage"]}')
# sewer cap
sew = sum(float(r['discharge_volume_gal']) for r in fp if r['discharge_route'] == 'SEWER')
haul = sum(float(r['discharge_volume_gal']) for r in fp if r['discharge_route'] == 'HAUL')
if sew > 500000: errs.append('cap')
# daily water from schedule
days = defaultdict(float)
for r in sc:
    s, f, w = float(r['start_h']), float(r['finish_h']), float(r['water_draw_gal'])
    if w <= 0 or f <= s: continue
    for d in range(int(s // 24), int(f // 24) + 1):
        ov = max(0, min(f, 24 * d + 24) - max(s, 24 * d))
        days[d] += w * ov / (f - s)
cap = lambda d: 61000 if d in (2, 3) else (30000 if d == 6 else 92000)
for d, w in days.items():
    if w > cap(d): errs.append(f'water day {d}')
# milestones and crews
for r in sc:
    f = float(r['finish_h'])
    if f > 1128: errs.append('TM-4')
    if r['stage'] == 'CHEM_CLEAN' and f > 528: errs.append('TM-2')
    if r['stage'] == 'HYDRO' and f > 144: errs.append('TM-1')
crews = set(r['crew_id'] for r in sc if r['crew_id'] not in ('NONE', ''))
if len(crews) > 2: errs.append('crews')
# governing lines
gl = re.findall(r'^GOVERNING CONSTRAINT (C\d): (.+) \(margin ([0-9.]+)\)$', mop, re.M)
if len(gl) != 8: errs.append(f'governing lines {len(gl)}')
# register documents
badocs = ['3-240-13', 'REV A', '40 CFR 122', '22 11 23', 'VD-08', 'RFI-009']
for r in rg:
    if any(b in r['document'].upper() for b in badocs): errs.append(f'register bad doc {r["id"]} {r["document"]}')
print('sewer', round(sew), 'haul', round(haul), 'max day', round(max(days.values())), 'rows', len(fp), len(ch), len(am), len(sc), len(rg))
print('cost total', res['cost']['total_usd'])
print('ERRORS:', errs if errs else 'none')

